'use strict';
const $=s=>document.querySelector(s), app=$('#app');
const names=['Jardim dos números','Trilha dos padrões','Ponte do equilíbrio','Oficina de invenções','Radar espacial'];
const icons=['✿','◆','⚖','✦','▦'];
let sound=false, running=false, paused=false, records=[], question=null, count=0, total=10, startLevel=1, levels=[1,1,1,1,1], streak=[0,0,0,0,0], seen=new Set(), sessionStart=null;
let started=0, pauseAt=0, pauseMs=0, tries=0, hints=0, selected=[], answered=false, notes='', configTotal=10, configLevel=1;
const rand=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const shuffle=a=>a.slice().sort(()=>Math.random()-.5);
const options=(n,min=0)=>shuffle([...new Set([n,Math.max(min,n-1),n+1,n+2,n+3])].slice(0,4));
function speak(s){if(sound&&'speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(s);u.lang='pt-BR';u.rate=.85;speechSynthesis.speak(u)}}
function home(){app.innerHTML=`<section class="hero"><div><div class="eyebrow"><i class="dot"></i> UMA AVENTURA DE DESCOBERTAS</div><h1>Pequenas ideias.<br><em>Grandes universos.</em></h1><p class="lead">A nave do Tico precisa da sua imaginação. Vamos brincar com números, descobrir caminhos e explorar o espaço?</p><button class="primary start" id="start">Vamos decolar <span aria-hidden="true">↗</span></button><p class="tiny">6+ anos &nbsp; · &nbsp; Sem corrida contra o relógio &nbsp; · &nbsp; Com um adulto</p></div><div class="space" aria-label="Tico, um simpático robô explorador entre planetas" role="img"><span class="star" style="top:45px;left:49%">✦</span><span class="star" style="top:150px;right:45px">✧</span><span class="star" style="bottom:100px;left:50px">+</span><span class="star" style="bottom:74px;left:39%">✧</span><div class="planet"></div><div class="moon"></div><div class="stamp">MISSÃO<br>DESCOBRIR</div><div class="robot"><div class="face"><div class="visor"><i class="eye"></i><i class="eye"></i></div></div><div class="body">✳</div></div><div class="bubble">Oi! Eu sou o Tico. Vamos juntos?</div></div></section><section class="intro-bottom"><div class="feature"><div class="icon">✿</div><div><h3>Cada missão, uma surpresa</h3><p>Números, padrões e ideias para experimentar.</p></div></div><div class="feature"><div class="icon">↗</div><div><h3>Uma aventura no seu ritmo</h3><p>Peça uma pista, faça uma pausa e tente de novo.</p></div></div><div class="feature"><div class="icon">✧</div><div><h3>O seu jeito de pensar importa</h3><p>Conte ao adulto como você descobriu!</p></div></div></section>`;$('#start').onclick=start;}
function start(){records=[];levels=Array(5).fill(configLevel);streak=Array(5).fill(0);seen.clear();count=0;total=configTotal;notes='';$('#notes').value='';sessionStart=new Date().toISOString();running=true;next();}
function make(type,l){let q={type,level:l},a,b,n;
if(type===0){a=rand(2,l===1?5:l===2?10:17);b=rand(1,l===1?4:l===2?8:12);let minus=l>1&&rand(0,1);if(minus&&a<b)[a,b]=[b,a];n=minus?a-b:a+b;q={...q,title:minus?'Estrelas de partida':'Um jardim de estrelas',prompt:minus?`Havia ${a} estrelas. ${b} viajaram. Quantas ficaram?`:`Há ${a} estrelas aqui e ${b} ${b===1?'chegou':'chegaram'}. Quantas temos juntas?`,visual:l===1?`<span>${'★'.repeat(a)}</span><span>+</span><span>${'★'.repeat(b)}</span>`:`${a} ${minus?'−':'+'} ${b} = ?`,answer:n,choices:options(n),hint:minus?'Imagine as estrelas saindo. Você pode usar os dedos ou desenhar.':'Comece com o primeiro grupo e junte o segundo. Pode usar objetos!',key:`0:${a}:${b}:${minus}`};}
if(type===1){if(l===1){const shapes=shuffle(['●','▲','◆']);let x=shapes[0],y=shapes[1];q={...q,title:'O caminho secreto',prompt:'Qual figura continua este caminho?',visual:`${x} ${y} ${x} ${y} ${x} <span class="symbol">?</span>`,answer:y,choices:shuffle(['●','▲','◆','■']),hint:'Olhe para as figuras que aparecem juntas. O que se repete?',key:`1:${x}:${y}`};}else{a=rand(1,5);b=rand(2,l===2?4:6);const seq=l===3?[a,a+b,a+2*b+1,a+3*b+3]:[a,a+b,a+2*b,a+3*b];n=l===3?a+4*b+6:a+4*b;q={...q,title:'Pegadas misteriosas',prompt:'Qual número vem depois? Conte como pensou.',visual:seq.join(' · ')+' · ?',answer:n,choices:options(n),hint:l===3?'Compare o tamanho de cada salto. Será que os saltos também mudam?':'Descubra de quanto é o salto entre dois números.',key:`1:${l}:${a}:${b}`};}}
if(type===2){a=rand(2,l===1?5:l===2?10:16);n=rand(1,l===1?4:l===2?9:15);b=a+n;q={...q,title:'Conserte a ponte',prompt:'Que número deixa os dois lados com o mesmo valor?',visual:`${a} + <span class="symbol">?</span> = ${b}`,answer:n,choices:options(n),hint:`Quanto falta para ir de ${a} até ${b}? Você pode contar ou desenhar.`,key:`2:${a}:${n}`};}
if(type===3){n=rand(l===1?4:l===2?7:11,l===1?7:l===2?12:18);let vals=shuffle([1,2,3,4,5,6]);if(l===3)vals=shuffle([2,3,4,5,7,8]);q={...q,title:'Combustível de ideias',prompt:`Escolha peças que somem ${n}. Pode haver mais de um jeito!`,visual:`✦ &nbsp; META ${n} &nbsp; ✦`,answer:n,choices:vals,hint:'Toque nas peças para juntar. Toque de novo para tirar. Experimente combinações!',key:`3:${n}:${vals.join(',')}`,multi:true};}
if(type===4){const grids=l===1?[[1,2,3],[1,2,3],[1,2,3]]:l===2?[[1,2,3],[2,3,4],[3,4,5]]:[[2,4,6],[3,6,9],[4,8,12]];a=rand(0,2);b=rand(0,2);n=grids[a][b];q={...q,title:'O mapa incompleto',prompt:'Observe as linhas e colunas. Que número falta no mapa?',visual:`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">${grids.flatMap((row,i)=>row.map((v,j)=>`<span class="symbol">${i===a&&j===b?'?':v}</span>`)).join('')}</div>`,answer:n,choices:options(n,1),hint:l===1?'Compare as linhas: o que elas têm em comum?':l===2?'Observe como os números mudam ao ir para o lado e para baixo.':'Compare o primeiro, o segundo e o terceiro número de cada linha.',key:`4:${l}:${a}:${b}`};}return q;}
function next(){if(count>=total){finish();return}const type=count%5;let q;for(let i=0;i<30;i++){q=make(type,levels[type]);if(!seen.has(q.key))break}seen.add(q.key);question=q;tries=0;hints=0;selected=[];answered=false;paused=false;pauseMs=0;started=performance.now();render();speak(q.prompt);}
function render(){const q=question;app.innerHTML=`<div class="game-top"><span class="eyebrow">MISSÃO ${count+1} / ${total}</span><div class="progress" aria-label="${count} de ${total} missões concluídas"><div style="width:${count/total*100}%"></div></div><button id="pause">Ⅱ Pausa</button></div><div class="game-shell"><aside class="guide"><div class="mini">🤖</div><h3>Vamos descobrir?</h3><p>Você pode pensar com calma, usar os dedos, desenhar e contar sua ideia.</p><div class="level">${icons[q.type]} ${names[q.type]}</div><p>Não precisa acertar de primeira. Explorar também faz parte!</p></aside><section class="challenge"><div class="tag">${icons[q.type]} ${names[q.type].toUpperCase()}</div><h2 tabindex="-1">${q.title}</h2><p class="prompt">${q.prompt}</p><div class="visual" aria-label="${q.type===4?'Mapa numérico de três linhas e três colunas':q.type===0&&q.level===1?q.prompt:q.visual.replace(/<[^>]*>/g,' ')}">${q.visual}</div><div class="choices" style="${q.multi?'grid-template-columns:repeat(3,1fr)':''}">${q.choices.map((v,i)=>`<button class="choice" data-i="${i}" ${q.multi?'aria-pressed="false"':''}>${v}</button>`).join('')}</div>${q.multi?'<div class="sum-total" aria-live="polite">Sua nave tem <strong id="sum">0</strong> de '+q.answer+' unidades</div><button class="primary" id="check">Testar minha ideia</button>':''}<div id="feedback" aria-live="polite"></div><div class="actions"><button id="hint">✧ Uma pista</button><button id="read">◖ Ouvir</button><button id="skip">Explorar outra →</button></div></section></div>`;document.querySelectorAll('.choice').forEach(btn=>btn.onclick=()=>choose(+btn.dataset.i));$('#hint').onclick=hint;$('#read').onclick=()=>{if('speechSynthesis'in window){let u=new SpeechSynthesisUtterance(q.prompt);u.lang='pt-BR';u.rate=.85;speechSynthesis.cancel();speechSynthesis.speak(u)}else feedback('A leitura por voz não está disponível neste navegador. O adulto pode ler junto.','hint')};$('#skip').onclick=()=>complete('pulou');$('#pause').onclick=pause;if(q.multi)$('#check').onclick=()=>answer(selected.reduce((s,i)=>s+q.choices[i],0));$('.challenge h2').focus({preventScroll:true});}
function choose(i){if(answered)return;if(question.multi){selected.includes(i)?selected=selected.filter(x=>x!==i):selected.push(i);document.querySelectorAll('.choice').forEach((b,j)=>{b.classList.toggle('selected',selected.includes(j));b.setAttribute('aria-pressed',selected.includes(j))});$('#sum').textContent=selected.reduce((s,j)=>s+question.choices[j],0);}else answer(question.choices[i]);}
function feedback(msg,cls=''){ $('#feedback').innerHTML=`<div class="feedback ${cls}">${msg}</div>`;}
function hint(){if(answered)return;hints++;feedback(question.hint,'hint');speak(question.hint);}
function answer(v){if(answered)return;tries++;question.responses=question.responses||[];question.responses.push({value:v,pieces:question.multi?selected.map(i=>question.choices[i]):undefined});if(v===question.answer){answered=true;save('resolveu');feedback('✦ Você descobriu! Como você pensou? Conte ao adulto.<div class="actions"><button id="next" class="primary">Próxima descoberta →</button></div>');$('#next').onclick=()=>{count++;next()};$('#hint').disabled=true;$('#skip').disabled=true;document.querySelectorAll('.choice').forEach(b=>b.disabled=true);if($('#check'))$('#check').disabled=true;celebrate();speak('Você descobriu! Como você pensou?');}else{feedback('Essa ideia ainda não completou a missão. Vamos experimentar outro jeito?','hint');speak('Vamos experimentar outro jeito?');}}
function save(status){const q=question;records.push({mission:count+1,category:names[q.type],level:q.level,prompt:q.prompt,visual:q.type===4?q.visual.replace(/<[^>]*>/g,' '):undefined,choices:q.choices,expected:q.answer,status,attempts:tries,hints,seconds:Math.round((performance.now()-started-pauseMs)/1000),responses:q.responses||[]});if(status==='resolveu'&&tries===1&&hints===0){streak[q.type]++;if(streak[q.type]>=1){levels[q.type]=Math.min(3,levels[q.type]+1);streak[q.type]=0}}else{streak[q.type]=0;if(status==='pulou'||tries>=3)levels[q.type]=Math.max(1,levels[q.type]-1)}}
function complete(status){if(answered)return;save(status);count++;next()}
function pause(){if(paused)return;paused=true;pauseAt=performance.now();if('speechSynthesis'in window)speechSynthesis.cancel();app.innerHTML='<section class="pause"><div style="font-size:60px">☾</div><h1>Uma pausa nas estrelas.</h1><p>Alongue os braços, respire e volte quando quiser.</p><div class="actions" style="justify-content:center"><button class="primary" id="resume">Voltar à aventura</button><button id="end">Encerrar sessão</button></div></section>';$('#resume').onclick=()=>{pauseMs+=performance.now()-pauseAt;paused=false;const keep={tries,hints,selected: selected.slice(),answered};render();tries=keep.tries;hints=keep.hints;selected=keep.selected;if(question.multi){document.querySelectorAll('.choice').forEach((b,j)=>{b.classList.toggle('selected',selected.includes(j));b.setAttribute('aria-pressed',selected.includes(j))});$('#sum').textContent=selected.reduce((s,i)=>s+question.choices[i],0)}if(keep.answered){answered=true;document.querySelectorAll('.choice').forEach(b=>b.disabled=true);$('#hint').disabled=true;$('#skip').disabled=true;if($('#check'))$('#check').disabled=true;feedback('✦ Missão concluída!<div class="actions"><button id="next" class="primary">Próxima descoberta →</button></div>');$('#next').onclick=()=>{count++;next()}}};$('#end').onclick=finish;}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<10;i++){const e=document.createElement('span');e.className='motion-star';e.textContent=['✦','✧','★'][i%3];e.style.left=rand(25,75)+'vw';e.style.top=rand(45,75)+'vh';e.style.color=['#dc976c','#9ab868','#599795'][i%3];document.body.append(e);setTimeout(()=>e.remove(),1100)}}
function finish(){if(running&&paused&&!answered){pauseMs+=performance.now()-pauseAt;save('interrompeu')}running=false;if('speechSynthesis'in window)speechSynthesis.cancel();app.innerHTML=`<section class="finish"><div class="big">🪐</div><div class="eyebrow" style="justify-content:center">CADERNO DE DESCOBERTAS</div><h1>O universo ficou<br><em>maior com suas ideias.</em></h1><p>Você explorou ${records.length} missões com o Tico.<br>Qual foi a sua descoberta favorita?</p><div class="medals"><div class="medal">✦ Curiosidade</div><div class="medal">✿ Novas ideias</div><div class="medal">◆ Exploração</div></div><p class="muted">Cada jeito de pensar abre um novo caminho.</p><div class="actions" style="justify-content:center"><button class="primary" id="again">Nova aventura</button><button id="see">Ver caderno de bordo</button></div><p class="muted">Exporte o registro antes de iniciar outra aventura.</p></section>`;$('#again').onclick=start;$('#see').onclick=openPanel;}
function openPanel(){if(running&&!paused){pause()}$('#report').innerHTML=`${!running?`<div class="config"><label>Tamanho da próxima aventura<select id="length"><option value="5">5 missões · uma rodada</option><option value="10">10 missões · duas rodadas</option><option value="15">15 missões · três rodadas</option></select></label><label>Dificuldade inicial<select id="level"><option value="1">1 · Descobrir (concreto)</option><option value="2">2 · Conectar (ampliado)</option><option value="3">3 · Investigar (complexo)</option></select></label></div>`:''}<p class="muted">Nível ajustado por categoria: sobe após uma solução independente na primeira tentativa; diminui após pular ou resolver com três ou mais tentativas. Não há comparação com outras crianças. Tempo inclui leitura e conversa; não é medida de capacidade. Abrir este painel pausa a missão.</p><p><strong>${records.length}</strong> missões registradas · <strong>${records.filter(r=>r.status==='resolveu').length}</strong> resolvidas · <strong>${records.reduce((s,r)=>s+r.hints,0)}</strong> pistas</p><div class="table-wrap"><table><thead><tr><th>Missão / nível</th><th>Registro</th><th>Tentativas</th><th>Pistas</th><th>Tempo*</th></tr></thead><tbody>${records.map(r=>`<tr><td>${r.mission}. ${r.category}<br>Nível ${r.level}</td><td>${r.status}</td><td>${r.attempts}</td><td>${r.hints}</td><td>${r.seconds}s</td></tr>`).join('')||'<tr><td colspan="5">Comece uma aventura para acompanhar as descobertas.</td></tr>'}</tbody></table></div><p class="muted">Perguntas para a conversa: “Como você descobriu?”, “Tem outro jeito?”, “O que mudaria se…?”. Observe estratégias, interesse, explicações e contexto. O registro não gera escore, classificação ou indicação diagnóstica.</p>`;if($('#length')){$('#length').value=configTotal;$('#length').onchange=e=>configTotal=+e.target.value;$('#level').value=configLevel;$('#level').onchange=e=>configLevel=+e.target.value;}$('#panel').showModal();}
$('#adult').onclick=openPanel;$('#close').onclick=()=>$('#panel').close();$('#notes').oninput=e=>notes=e.target.value;$('#sound').onclick=()=>{sound=!sound;$('#sound').setAttribute('aria-pressed',sound);$('#sound').innerHTML='♬ <span>Som '+(sound?'ligado':'desligado')+'</span>';if(sound)speak('Olá! Eu sou o Tico. Vamos explorar?');else if('speechSynthesis'in window)speechSynthesis.cancel()};$('#export').onclick=()=>{const data={game:'Órbita',version:1,sessionStart,exportedAt:new Date().toISOString(),plannedMissions:total,incomplete:records.length<total||records.some(r=>r.status==='interrompeu'),records,notes,notice:'Registro descritivo de atividade lúdica sem validade psicométrica. Não utilizar como diagnóstico ou classificação de altas habilidades.'};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='orbita-registro-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#print').onclick=()=>window.print();$('.brand').onclick=e=>{e.preventDefault();if(!running)home();else pause()};home();
